      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      sentence = "I had always just said that I wanted to give it a try, but I'd never explained to him where this notion to give it a try had come from.",
      next = {4}
    },
    [4] = {
      beijing = 2550,
      dhead = 111,
      dialog = 1,
      music = "24_Romantic_Quiet",
      renming = "$u",
      renwu = "npc",
      sentence = "One time I stayed up all night finishing a presentation, and so the next day I ended up sleeping until five in the afternoon. Do you remember that?",
      next = {5}
    },
    [5] = {
      beijing = 2550,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      sentence = "At the time, just a hair of light was spilling in from behind the curtain. It was the dusky rays of the setting sun lighting up the wooden floor.",
      next = {6}
    },
    [6] = {
      beijing = 2550,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      sentence = "I was looking at this sliver of light swaying in the breeze, still not fully awake from my exhausted slumber, and I had this ineffable feeling of comfort.",
      next = {7}
    },
    [7] = {
      beijing = 2550,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      sentence = "And just then, I got a call from Gavin.",
      next = {8}
    },
    [8] = {
      beijing = 2550,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "24_Romantic_Quiet",
      renming = "Gavin",
      renwu = "npc",
      role1 = 402000,
      role2 = 402110,
      role3 = 402202,
      role5 = 402401,
      ruchang = -1,
      sentence = "I remember. When I called you, you were still too tired to get out of bed, counting on your fingers how many hours you slept.",
      voice = 2,
      next = {9}
    },
    [9] = {
      beijing = 2550,
      dialog = 2,
      idx = 4,
