      renming = "Gavin",
      renwu = "npc",
      role1 = 402000,
      role2 = 402107,
      role3 = 402202,
      role5 = 402401,
      sentence = "And you were complaining about how since you slept all day, you hadn't eaten all day, so you asked me to get some takeout for you.",
